    for r in range(h - 1):
        for c in range(w):
            v = g[r][c]
            if not v:
                continue
            try:
                idx = motif.index(v)
            except ValueError:
                continue
            start = c - idx
            for j, color in enumerate(motif):
                x = start + j
                if 0 <= x < w:
                    g[r][x] = color
    return g
