    h, w = len(g), len(g[0])

    def runs(row):
        result, c = [], 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            seq = []
            while c < w and row[c] != 0:
                seq.append(row[c])
                c += 1
            result.append(seq)
        return result

    keys = runs(g[0]) + runs(g[-1])
    anchors = []
    for r in range(1, h - 1):
        for c in range(w):
            color = g[r][c]
            if not color:
                continue
            if ((r and g[r - 1][c]) or (r + 1 < h and g[r + 1][c]) or
                    (c and g[r][c - 1]) or (c + 1 < w and g[r][c + 1])):
                continue
            candidates = [key for key in keys if color in key]
